// Symbol Table Entry for Linking
typedef struct {
    const char *name;
    enum { DEFINED, UNDEFINED } status;
    uintptr_t target_addr; // Final resolved address
} SymbolEntry;

// Object File A Symbol Table (Needs external reference)
SymbolEntry SymTable_A[] = {
    {"main", DEFINED, 0x1000},
    {"logger_init", UNDEFINED, 0} // External
};

// Library B Symbol Table (Provides definition)
SymbolEntry SymTable_B[] = {
    {"logger_init", DEFINED, 0x8500}
};

// Linker Resolution Step:
// SymTable_A[1].target_addr = SymTable_B[0].target_addr;
// Symbol "logger_init" resolved to 0x8500
// status changes to DEFINED (in final executable image)
